package org.eclipse.rdf4j.query.algebra.evaluation.function.string;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class StrLenTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private final StrLen function = new StrLen();

	@Test
	void countsSupplementaryCharactersAsSingleCharacters() {
		assertEquals(3, function.evaluate(VF, VF.createLiteral("A😀𐐷")).intValue());
	}

	@Test
	void countsUnicodeCodePointsRatherThanGraphemeClusters() {
		assertEquals(2, function.evaluate(VF, VF.createLiteral("e\u0301")).intValue());
	}
}
